const ship = (x) => x && x.rv && x.rv.verdict === 'ship' && !x.rv.issues.some(i => i.severity === 'must-fix')
const runWeek = async (wk) => {
  const posts = ['nz', 'global'].flatMap(ed => (prog.calendars[ed].weeks.find(w => w.week === wk) || { posts: [] }).posts.map(p => ({ ...p, edition: ed, week: wk }))).filter(p => !p.existing_project)
  log(`week ${wk}: ${posts.length} videos`)
  const res = await pipeline(posts,
    p => produce(p),
    (r, p) => r ? review(p, r).then(rv => ({ r, rv })) : null,
    (x, p) => x ? (ship(x) ? Promise.resolve({ ...x.r, review: x.rv, fixed: false }) : fix(p, x.r, x.rv).then(f => ({ ...(f || x.r), review: x.rv, fixed: !!f }))) : null,
  )
  return res.map((r, i) => ({ week: wk, slot: posts[i], result: r }))
}
const existing = () => pipeline(JOBS,
  j => agent(`You are the producer, editor and motion designer for an already-made QSME video that needs one more pass before it's posted. An earlier run of this task was INTERRUPTED part-way: inspect the project folder first and continue from whatever is already there.\n${CONTEXT}\n\nPROJECT: ${j.folder}\nCALENDAR SLOT: ${JSON.stringify(j.slot)}\nTASK: ${j.task}\nUse ${U}/tools/motion (README, kit.js API, make.mjs with --safe; QA must pass). READ the -frames.png contact sheet and spot-check key moments with ${U}/tools/motion/frames <mp4> <dir> 540 t1 t2 … and iterate until it is genuinely good. Add a dated line under 'Discussion history' in post.md. Only touch ${j.folder}. No deploys, no paid APIs. Return the result object (mp4 = the main new output).`, { label: `redo:${j.folder.split('-').slice(-3).join('-')}`, phase: 'Existing', schema: PRODUCED }),
  (r, j) => r ? review(j.slot, r).then(rv => ({ r, rv })) : null,
  (x, j) => x ? (ship(x) ? Promise.resolve({ ...x.r, review: x.rv, fixed: false }) : fix(j.slot, x.r, x.rv).then(f => ({ ...(f || x.r), review: x.rv, fixed: !!f }))) : null,
)
const [studio, ex, w3] = await parallel([studioChain, existing, () => runWeek(3)])
const w4 = await runWeek(4)
return { studio, existing: ex, week3: w3, week4: w4 }
